    <style>
        :root {
            bggradient: lineargradient(120deg, f6f8fc 0%, e9f0fa 100%);
            glassbg: rgba(255,255,255,0.7);
            glassbghover: rgba(255,255,255,0.85);
            glassborder: rgba(180,200,255,0.18);
            accent: 7b8cff;
            accentsoft: e6eaff;
            accentgradient: lineargradient(90deg, 7b8cff 0%, b7aaff 100%);
            textmain: 222;
            textsecondary: 5a6a8a;
            shadow: 0 8px 32px 0 rgba(60,80,120,0.10);
            radius: 32px;
        }

        html, body {
            height: 100%;
            margin: 0;
            padding: 0;
        }
        body {
            minheight: 100vh;
            fontfamily: 'Inter', applesystem, BlinkMacSystemFont, sansserif;
            background: var(bggradient);
            color: var(textmain);
            fontweight: 300;
            lineheight: 1.7;
            overflowx: hidden;
            position: relative;
        }

        / Floating glass blobs for 2035 feel /
        .liquidbg {
            position: fixed;
            inset: 0;
            zindex: 1;
            pointerevents: none;
        }
        .liquidbg::before, .liquidbg::after {
            content: '';
            position: absolute;
            borderradius: 50%;
            filter: blur(60px);
            opacity: 0.5;
            pointerevents: none;
        }
        .liquidbg::before {
            width: 600px; height: 600px;
            left: 200px; top: 100px;
            background: lineargradient(120deg, b7aaff 0%, e6eaff 100%);
        }
        .liquidbg::after {
            width: 400px; height: 400px;
            right: 100px; bottom: 100px;
            background: lineargradient(120deg, 7b8cff 0%, e6eaff 100%);
        }

        .container {
            maxwidth: 700px;
            margin: 0 auto;
            padding: 0 24px;
        }

        header {
            textalign: center;
            padding: 18vh 0 10vh;
        }
        h1 {
            fontsize: clamp(2.8rem, 8vw, 5rem);
            fontweight: 200;
            letterspacing: 0.04em;
            color: var(textmain);
            marginbottom: 2.5rem;
            background: var(accentgradient);
            backgroundclip: text;
            webkitbackgroundclip: text;
            color: transparent;
            webkittextfillcolor: transparent;
            filter: dropshadow(0 2px 8px rgba(123,140,255,0.08));
        }

        .ctabtn {
            background: var(glassbg);
            border: 1.5px solid var(glassborder);
            color: var(accent);
            padding: 18px 44px;
            borderradius: 999px;
            fontsize: 1.1rem;
            fontweight: 400;
            letterspacing: 0.04em;
            cursor: pointer;
            boxshadow: var(shadow);
            transition: all 0.25s cubicbezier(.4,0,.2,1);
            outline: none;
            margintop: 1rem;
        }
        .ctabtn:hover, .ctabtn:focus {
            background: var(glassbghover);
            color: fff;
            bordercolor: var(accent);
            boxshadow: 0 8px 32px 0 rgba(123,140,255,0.10);
        }

        / Modal /
        .modal {
            position: fixed;
            inset: 0;
            background: rgba(240,245,255,0.65);
            backdropfilter: blur(16px);
            display: none;
            alignitems: center;
            justifycontent: center;
            zindex: 1000;
            opacity: 0;
            transition: opacity 0.4s;
        }
        .modal.active {
            display: flex;
            opacity: 1;
        }
        .modalcontent {
            background: var(glassbg);
            border: 1.5px solid var(glassborder);
            borderradius: var(radius);
            padding: 48px 32px 32px 32px;
            maxwidth: 420px;
            width: 95vw;
            boxshadow: var(shadow);
            position: relative;
            animation: modalEntry 0.5s cubicbezier(.4,0,.2,1);
        }
        @keyframes modalEntry {
            0% { transform: scale(0.96) translateY(30px); opacity: 0; }
            100% { transform: scale(1) translateY(0); opacity: 1; }
        }
        .modalclose {
            position: absolute;
            top: 18px; right: 22px;
            background: none;
            border: none;
            fontsize: 2rem;
            color: var(textsecondary);
            cursor: pointer;
            borderradius: 50%;
            width: 36px; height: 36px;
            display: flex; alignitems: center; justifycontent: center;
            transition: background 0.2s;
        }
        .modalclose:hover {
            background: var(accentsoft);
            color: var(accent);
        }
        .modaltitle {
            fontsize: 2rem;
            fontweight: 300;
            textalign: center;
            marginbottom: 32px;
            letterspacing: 0.01em;
            color: var(textmain);
        }
        .featuresgrid {
            display: flex;
            flexdirection: column;
            gap: 18px;
            marginbottom: 32px;
        }
        .featureitem {
            background: var(glassbg);
            border: 1.5px solid var(glassborder);
            borderradius: 20px;
            padding: 22px 20px;
            cursor: pointer;
            transition: all 0.2s cubicbezier(.4,0,.2,1);
            boxshadow: 0 2px 8px 0 rgba(123,140,255,0.04);
            position: relative;
        }
        .featureitem:hover, .featureitem.active {
            bordercolor: var(accent);
            background: var(accentsoft);
            boxshadow: 0 4px 16px 0 rgba(123,140,255,0.08);
        }
        .featurename {
            fontsize: 1.1rem;
            fontweight: 400;
            color: var(textmain);
        }
        .featuredesc {
            fontsize: 0.95rem;
            color: var(textsecondary);
        }
        .startbtn {
            width: 100%;
            background: var(accentgradient);
            color: fff;
            border: none;
            padding: 18px 0;
            borderradius: 999px;
            fontsize: 1.1rem;
            fontweight: 500;
            cursor: pointer;
            boxshadow: 0 4px 16px 0 rgba(123,140,255,0.10);
            transition: all 0.2s cubicbezier(.4,0,.2,1);
        }
        .startbtn:disabled {
            opacity: 0.4;
            cursor: notallowed;
        }
        .startbtn:not(:disabled):hover {
            filter: brightness(1.08);
            boxshadow: 0 8px 32px 0 rgba(123,140,255,0.13);
        }

        / Generator Card /
        .generatorcard {
            background: var(glassbg);
            border: 1.5px solid var(glassborder);
            borderradius: var(radius);
            padding: 48px 32px;
            margin: 48px 0;
            display: none;
            boxshadow: var(shadow);
            animation: cardSlideUp 0.7s cubicbezier(.4,0,.2,1);
        }
        .generatorcard.active {
            display: block;
        }
        @keyframes cardSlideUp {
            0% { opacity: 0; transform: translateY(40px);}
            100% { opacity: 1; transform: translateY(0);}
        }
        .cardtitle {
            fontsize: 2rem;
            fontweight: 300;
            textalign: center;
            marginbottom: 36px;
            color: var(textmain);
        }
        .formgroup {
            marginbottom: 32px;
        }
        label {
            display: block;
            marginbottom: 10px;
            fontweight: 400;
            fontsize: 1rem;
            color: var(textmain);
        }
        input, textarea, select {
            width: 100%;
            padding: 16px;
            border: 1.5px solid var(glassborder);
            borderradius: 16px;
            background: var(glassbg);
            color: var(textmain);
            fontsize: 1.05rem;
            fontfamily: inherit;
            fontweight: 300;
            transition: border 0.2s, boxshadow 0.2s;
            boxshadow: 0 1px 4px 0 rgba(123,140,255,0.04);
        }
        input:focus, textarea:focus, select:focus {
            outline: none;
            bordercolor: var(accent);
            boxshadow: 0 2px 8px 0 rgba(123,140,255,0.10);
        }
        textarea {
            minheight: 100px;
            resize: vertical;
        }
        .generatebtn {
            width: 100%;
            background: var(accentgradient);
            color: fff;
            border: none;
            padding: 18px 0;
            borderradius: 999px;
            fontsize: 1.1rem;
            fontweight: 500;
            cursor: pointer;
            boxshadow: 0 4px 16px 0 rgba(123,140,255,0.10);
            transition: all 0.2s cubicbezier(.4,0,.2,1);
        }
        .generatebtn:disabled {
            opacity: 0.4;
            cursor: notallowed;
        }
        .generatebtn:not(:disabled):hover {
            filter: brightness(1.08);
            boxshadow: 0 8px 32px 0 rgba(123,140,255,0.13);
        }

        / Loading /
        .loading {
            display: none;
            textalign: center;
            padding: 48px 0;
            background: var(glassbg);
            border: 1.5px solid var(glassborder);
            borderradius: var(radius);
            margintop: 32px;
            boxshadow: var(shadow);
        }
        .loading.active {
            display: block;
            animation: fadeIn 0.4s;
        }
        @keyframes fadeIn {
            0% { opacity: 0;}
            100% { opacity: 1;}
        }
        .spinner {
            width: 48px; height: 48px;
            border: 3px solid var(glassborder);
            bordertop: 3px solid var(accent);
            borderradius: 50%;
            animation: spin 1.2s linear infinite;
            margin: 0 auto 18px;
        }
        @keyframes spin {
            0% { transform: rotate(0deg);}
            100% { transform: rotate(360deg);}
        }
        .loadingtext {
            color: var(textsecondary);
            fontsize: 1.1rem;
            fontweight: 300;
        }

