        .resultsgrid {
            display: grid;
            gridtemplatecolumns: 1fr;
            gap: 32px;
            margintop: 48px;
        }
        .resultcard {
            background: var(glassbg);
            border: 1.5px solid var(glassborder);
            borderradius: 24px;
            padding: 32px;
            boxshadow: var(shadow);
            transition: boxshadow 0.2s, border 0.2s, transform 0.2s;
        }
        .resultcard:hover {
            bordercolor: var(accent);
            boxshadow: 0 8px 32px 0 rgba(123,140,255,0.13);
            transform: translateY(4px) scale(1.01);
        }
        .resultcard h3 {
            fontsize: 1.1rem;
            fontweight: 400;
            marginbottom: 18px;
            color: var(textmain);
        }
        .resultcard img {
            width: 100%;
            borderradius: 16px;
            marginbottom: 18px;
            boxshadow: 0 2px 8px 0 rgba(123,140,255,0.06);
            transition: transform 0.2s;
        }
        .resultcard:hover img {
            transform: scale(1.02);
        }
        .downloadbtn {
            background: var(accentgradient);
            color: fff;
            border: none;
            padding: 12px 28px;
            borderradius: 999px;
            fontweight: 500;
            textdecoration: none;
            display: inlineblock;
            fontsize: 1rem;
            transition: filter 0.2s, boxshadow 0.2s;
            boxshadow: 0 2px 8px 0 rgba(123,140,255,0.08);
        }
        .downloadbtn:hover {
            filter: brightness(1.08);
            boxshadow: 0 4px 16px 0 rgba(123,140,255,0.13);
        }
        .error {
            background: fff0f0;
            border: 1.5px solid ffbdbd;
            color: d33;
            padding: 16px;
            borderradius: 16px;
            margintop: 12px;
            fontsize: 1rem;
        }

        @media (maxwidth: 600px) {
            .container { padding: 0 8px; }
            .generatorcard, .modalcontent { padding: 24px 8px; }
            .resultsgrid { gap: 18px; }
            header { padding: 10vh 0 6vh; }
            h1 { fontsize: clamp(2rem, 8vw, 3.2rem);}
            .modaltitle, .cardtitle { fontsize: 1.3rem;}
        }
    </style>
</head>
<body>
    <div class="liquidbg"></div>
    <div class="container">
        <header>
            <h1>Kollár Sándor</h1>
            <button class="ctabtn" id="betabtn">Béta Funkciók</button>
        </header>
        <div class="modal" id="betamodal">
            <div class="modalcontent">
                <button class="modalclose" id="modalclose">&times;</button>
                <h2 class="modaltitle">Béta Funkciók</h2>
                <div class="featuresgrid">
                    <div class="featureitem" datafeature="imagegenerator">
                        <div class="featurename">Képgenerátor AI</div>
                        <div class="featuredesc">It's TiffyTime!</div>
                    </div>
                </div>
                <button class="startbtn" id="startfeature" disabled>Válassz funkciót</button>
            </div>
        </div>
        <div class="generatorcard" id="imagegenerator">
            <h2 class="cardtitle">Képgenerátor</h2>
            <form id="generatorform">
                <div class="formgroup">
                    <label for="prompt">Prompt</label>
                    <textarea id="prompt" placeholder="Írj le részletesen, milyen képet szeretnél..." required></textarea>
                </div>
                <div class="formgroup">
                    <label for="aspectratio">Formátum</label>
                    <select id="aspectratio">
                        <option value="1:1">Négyzet</option>
                        <option value="9:16">Mobil</option>
                        <option value="16:9">Széles</option>
                        <option value="4:3">Klasszikus</option>
                        <option value="3:4">Portré</option>
                    </select>
                </div>
                <button type="submit" class="generatebtn">Generál ás</button>
            </form>
        </div>
        <div class="loading" id="loading">
            <div class="spinner"></div>
            <p class="loadingtext" id="loadingtext">Dolgozok...</p>
        </div>
        <div class="resultsgrid" id="resultgrid"></div>
    </div>
    <script>
        const betaBtn = document.getElementById('betabtn');
        const betaModal = document.getElementById('betamodal');
        const modalClose = document.getElementById('modalclose');
        const featureItems = document.querySelectorAll('.featureitem');
        const startFeatureBtn = document.getElementById('startfeature');
        const imageGenerator = document.getElementById('imagegenerator');

        let selectedFeature = null;

        betaBtn.addEventListener('click', () => {
            betaModal.classList.add('active');
        });

        modalClose.addEventListener('click', () => {
            betaModal.classList.remove('active');
        });

        betaModal.addEventListener('click', (e) => {
            if (e.target === betaModal) {
                betaModal.classList.remove('active');
            }
        });

        featureItems.forEach(item => {
            item.addEventListener('click', () => {
                featureItems.forEach(i => i.classList.remove('active'));
                item.classList.add('active');
                selectedFeature = item.dataset.feature;

                if (selectedFeature === 'imagegenerator') {
                    startFeatureBtn.textContent = 'Indítás';
                    startFeatureBtn.disabled = false;
                }
            });
        });

        startFeatureBtn.addEventListener('click', () => {
            if (selectedFeature === 'imagegenerator') {
                betaModal.classList.remove('active');
                imageGenerator.classList.add('active');
                imageGenerator.scrollIntoView({ behavior: 'smooth' });
            }
        });

        function showLoading(text) {
            document.getElementById('loadingtext').textContent = text;
            document.getElementById('loading').classList.add('active');
        }

        function hideLoading() {
            document.getElementById('loading').classList.remove('active');
        }

        function displayResult(data) {
            const resultGrid = document.getElementById('resultgrid');
            resultGrid.innerHTML = '';

            data.results.forEach(result => {
                const resultItem = document.createElement('div');
                resultItem.className = 'resultcard';

                if (result.success) {
                    resultItem.innerHTML = 
                        <h3>${result.model}</h3>
                        <img src="${result.image_url}" alt="Generált kép" loading="lazy">
                        <a href="/download?url=${encodeURIComponent(result.image_url)}" class="downloadbtn">Letöltés</a>
                    ;
                } else {
                    resultItem.innerHTML = 
                        <h3>${result.model}</h3>
                        <div class="error">Hiba: ${result.error}</div>
                    ;
                }

                resultGrid.appendChild(resultItem);
            });
        }

        function displayError(message) {
            const resultGrid = document.getElementById('resultgrid');
            resultGrid.innerHTML = <div class="error">${message}</div>;
        }

        document.getElementById('generatorform').addEventListener('submit', async (e) => {
            e.preventDefault();

            const formData = {
                prompt: document.getElementById('prompt').value,
                aspect_ratio: document.getElementById('aspectratio').value
            };

            showLoading('Dolgozunk...');

            try {
                const response = await fetch('/generate_combined', {
                    method: 'POST',
                    headers: {
                        'ContentType': 'application/json',
                    },
                    body: JSON.stringify(formData)
                });

                const data = await response.json();

                if (data.success) {
                    displayResult(data);
                } else {
                    displayError(data.error || 'Hiba történt');
                }
            } catch (error) {
                displayError(Hiba: ${error.message});
            } finally {
                hideLoading();
            }
        });
    </script>
</body>
</html>

