    <script>
        const betaBtn = document.getElementById('betabtn');
        const betaModal = document.getElementById('betamodal');
        const modalClose = document.getElementById('modalclose');
        const featureItems = document.querySelectorAll('.featureitem');
        const startFeatureBtn = document.getElementById('startfeature');
        const imageGenerator = document.getElementById('imagegenerator');

        let selectedFeature = null;

        betaBtn.addEventListener('click', () => {
            betaModal.classList.add('active');
        });

        modalClose.addEventListener('click', () => {
            betaModal.classList.remove('active');
        });

        betaModal.addEventListener('click', (e) => {
            if (e.target === betaModal) {
                betaModal.classList.remove('active');
            }
        });

        featureItems.forEach(item => {
            item.addEventListener('click', () => {
                featureItems.forEach(i => i.classList.remove('active'));
                item.classList.add('active');
                selectedFeature = item.dataset.feature;

                if (selectedFeature === 'imagegenerator') {
                    startFeatureBtn.textContent = 'Indítás';
                    startFeatureBtn.disabled = false;
                }
            });
        });

        startFeatureBtn.addEventListener('click', () => {
            if (selectedFeature === 'imagegenerator') {
                betaModal.classList.remove('active');
                imageGenerator.classList.add('active');
                imageGenerator.scrollIntoView({ behavior: 'smooth' });
            }
        });

        function showLoading(text) {
            document.getElementById('loadingtext').textContent = text;
            document.getElementById('loading').classList.add('active');
        }

        function hideLoading() {
            document.getElementById('loading').classList.remove('active');
        }

        function displayResult(data) {
            const resultGrid = document.getElementById('resultgrid');
            resultGrid.innerHTML = '';

            data.results.forEach(result => {
                const resultItem = document.createElement('div');
                resultItem.className = 'resultcard';

                if (result.success) {
                    resultItem.innerHTML = 
                        <h3>${result.model}</h3>
                        <img src="${result.image_url}" alt="Generált kép" loading="lazy">
                        <a href="/download?url=${encodeURIComponent(result.image_url)}" class="downloadbtn">Letöltés</a>
                    ;
                } else {
                    resultItem.innerHTML = 
                        <h3>${result.model}</h3>
                        <div class="error">Hiba: ${result.error}</div>
                    ;
                }

                resultGrid.appendChild(resultItem);
            });
        }

        function displayError(message) {
            const resultGrid = document.getElementById('resultgrid');
            resultGrid.innerHTML = <div class="error">${message}</div>;
        }

        document.getElementById('generatorform').addEventListener('submit', async (e) => {
            e.preventDefault();

            const formData = {
                prompt: document.getElementById('prompt').value,
                aspect_ratio: document.getElementById('aspectratio').value
            };

            showLoading('Dolgozunk...');

            try {
                const response = await fetch('/generate_combined', {
                    method: 'POST',
                    headers: {
                        'ContentType': 'application/json',
                    },
                    body: JSON.stringify(formData)
                });

                const data = await response.json();

                if (data.success) {
                    displayResult(data);
                } else {
                    displayError(data.error || 'Hiba történt');
                }
            } catch (error) {
                displayError(Hiba: ${error.message});
            } finally {
                hideLoading();
            }
        });
    </script>
