            margin-top: 12px;
            font-size: 1rem;
        }
        body.dark-mode .error {
            background: #2a1a1a;
            border: 1.5px solid #5a2a2a;
            color: #ff7b7b;
        }

        @media (max-width: 600px) {
            .container { padding: 0 8px; }
            .generator-card, .modal-content { padding: 24px 8px; }
            .results-grid { gap: 18px; }
            header { padding: 0 0 6vh; }
            h1 { font-size: clamp(2rem, 8vw, 3.2rem);}
            .modal-title, .card-title { font-size: 1.3rem;}
            .main-content { padding-top: calc(var(--header-height) + 24px); }
        }
    </style>
</head>
<body>
    <header class="app-header">
        <span class="app-title">Kollár Sándor</span>
        <button class="dark-mode-toggle" id="dark-mode-toggle">
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z"/>
            </svg>
            <span id="dark-mode-text">Sötét mód</span>
        </button>
    </header>
    <div class="liquid-bg"></div>
    <div class="main-content">
        <div class="container">
            <header>
                <h1>Kollár Sándor</h1>
                <button class="cta-btn" id="beta-btn">Béta Funkciók</button>
            </header>
            <div class="modal" id="beta-modal">
                <div class="modal-content">
                    <button class="modal-close" id="modal-close">&times;</button>
                    <h2 class="modal-title">Béta Funkciók</h2>
                    <div class="features-grid">
                        <div class="feature-item" data-feature="image-generator">
                            <div class="feature-name">Képgenerátor AI</div>
                            <div class="feature-desc">It's TiffyTime!</div>
                        </div>
                    </div>
                    <button class="start-btn" id="start-feature" disabled>Válassz funkciót</button>
                </div>
            </div>
            <div class="generator-card" id="image-generator">
                <h2 class="card-title">Képgenerátor</h2>
                <form id="generator-form">
                    <div class="form-group">
                        <label for="prompt">Prompt</label>
                        <textarea id="prompt" placeholder="Írj le részletesen, milyen képet szeretnél..." required></textarea>
                    </div>
                    <div class="form-group">
                        <label for="aspect-ratio">Formátum</label>
                        <select id="aspect-ratio">
                            <option value="1:1">Négyzet</option>
                            <option value="9:16">Mobil</option>
                            <option value="16:9">Széles</option>
                            <option value="4:3">Klasszikus</option>
                            <option value="3:4">Portré</option>
                        </select>
                    </div>
                    <button type="submit" class="generate-btn">Generálás</button>
                </form>
            </div>
            <div class="loading" id="loading">
                <div class="spinner"></div>
                <p class="loading-text" id="loading-text">Dolgozok...</p>
            </div>
            <div class="results-grid" id="result-grid"></div>
        </div>
    </div>
    <script>
        const betaBtn = document.getElementById('beta-btn');
        const betaModal = document.getElementById('beta-modal');
        const modalClose = document.getElementById('modal-close');
        const featureItems = document.querySelectorAll('.feature-item');
        const startFeatureBtn = document.getElementById('start-feature');
        const imageGenerator = document.getElementById('image-generator');
        const darkModeToggle = document.getElementById('dark-mode-toggle');
        const darkModeText = document.getElementById('dark-mode-text');

        let selectedFeature = null;

        // Dark mode toggle
        darkModeToggle.addEventListener('click', () => {
            document.body.classList.toggle('dark-mode');
            if (document.body.classList.contains('dark-mode')) {
                darkModeText.textContent = 'Világos mód';
            } else {
                darkModeText.textContent = 'Sötét mód';
            }
        });

        // Modal logic
        betaBtn.addEventListener('click', () => {
            betaModal.classList.add('active');
        });

        modalClose.addEventListener('click', () => {
            betaModal.classList.remove('active');
        });

        betaModal.addEventListener('click', (e) => {
            if (e.target === betaModal) {
                betaModal.classList.remove('active');
            }
        });

        featureItems.forEach(item => {
            item.addEventListener('click', () => {
                featureItems.forEach(i => i.classList.remove('active'));
                item.classList.add('active');
                selectedFeature = item.dataset.feature;

                if (selectedFeature === 'image-generator') {
                    startFeatureBtn.textContent = 'Indítás';
                    startFeatureBtn.disabled = false;
                }
            });
        });

        startFeatureBtn.addEventListener('click', () => {
            if (selectedFeature === 'image-generator') {
                betaModal.classList.remove('active');
                imageGenerator.classList.add('active');
                imageGenerator.scrollIntoView({ behavior: 'smooth' });
            }
        });

        function showLoading(text) {
            document.getElementById('loading-text').textContent = text;
            document.getElementById('loading').classList.add('active');
        }

        function hideLoading() {
            document.getElementById('loading').classList.remove('active');
        }

        function displayResult(data) {
            const resultGrid = document.getElementById('result-grid');
            resultGrid.innerHTML = '';

            data.results.forEach(result => {
                const resultItem = document.createElement('div');
                resultItem.className = 'result-card';

                if (result.success) {
                    resultItem.innerHTML = `
                        <h3>${result.model}</h3>
                        <img src="${result.image_url}" alt="Generált kép" loading="lazy">
                        <a href="/download?url=${encodeURIComponent(result.image_url)}" class="download-btn">Letöltés</a>
                    `;
                } else {
                    resultItem.innerHTML = `
                        <h3>${result.model}</h3>
                        <div class="error">Hiba: ${result.error}</div>
                    `;
                }

                resultGrid.appendChild(resultItem);
            });
        }

        function displayError(message) {
            const resultGrid = document.getElementById('result-grid');
            resultGrid.innerHTML = `<div class="error">${message}</div>`;
        }

        document.getElementById('generator-form').addEventListener('submit', async (e) => {
            e.preventDefault();

            const formData = {
                prompt: document.getElementById('prompt').value,
                aspect_ratio: document.getElementById('aspect-ratio').value
            };

            showLoading('Dolgozunk...');

            try {
                const response = await fetch('/generate_combined', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                    },
                    body: JSON.stringify(formData)
                });

                const data = await response.json();

                if (data.success) {
                    displayResult(data);
                } else {
                    displayError(data.error || 'Hiba történt');
                }
            } catch (error) {
                displayError(`Hiba: ${error.message}`);
            } finally {
                hideLoading();
            }
        });
    </script>
</body>
</html>




 Főbb változtatások

 Modern, 2035es kinézet:  
   Tisztább, minimalista, letisztult dizájn.
   Áttetsző, matt üveg effektek.
   Lágy, harmonikus színek és árnyékok.
   Nem túl techno, inkább professzionális, elegáns.
